def is_costas(perm):
    """Check if a permutation is a Costas array."""
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
