def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find cycles
    from collections import deque

    for start in range(n):
        # BFS from start, tracking path
        visited = {start: [start]}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v == start and len(visited[u]) == length:
                    return True
                if v not in visited:
                    visited[v] = visited[u] + [v]
                    if len(visited[v]) < length:
                        queue.append(v)
    return False

def has_4_cycle(edges, n):
