    model = solver.get_model()
    edges = []
    for (i,j), var in edge_vars.items():
        if model[var-1] > 0:
            edges.append((i,j))
    print(f"SAT! Edges: {len(edges)}")

    # Check degrees
    degrees = [0]*n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}")
