def add_edges_for_min_degree(n, known_edges, target_degree=5):
    edges = list(known_edges)
    degree = [0] * n
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1

    changed = True
    while changed:
        changed = False
        low_deg = [(degree[v], v) for v in range(n) if degree[v] < target_degree]
        low_deg.sort()

        if not low_deg:
            break

        v1 = low_deg[0][1]
        for _, v2 in low_deg[1:]:
            if v1 < v2:
                edge = (v1, v2)
            else:
                edge = (v2, v1)

            if edge not in set(edges):
                edges.append(edge)
                degree[v1] += 1
                degree[v2] += 1
                changed = True
                break

    return edges

